// ---------------------------------------------------------------------------
// The bowl and everything in it. Units: bowl rim radius = 1.
// ---------------------------------------------------------------------------
const BROTH_Y = 0.62;
const RIM_Y = 0.74;
const H_EXT = 1.25;          // heightfield half extent (xz)
const H_RES = 1024;          // heightfield resolution
const H_MAX = 1.6;           // max encodable height
const LM_EXT = 2.0;          // light map half extent
const LM_RES = 768;
const LIGHT_POS = [-1.45, 4.35, -3.95];
const LIGHT_RAD = 0.85;

const bowlOuterR = (s) => 0.40 + 0.60 * (0.3 * s + 0.7 * (1 - (1 - s) * (1 - s)));
const bowlThick = (s) => 0.035 + 0.04 * (1 - s);
const innerR = (y) => { const s = (y - 0.065) / 0.675; return bowlOuterR(s) - bowlThick(s); };
const BROTH_R = innerR(BROTH_Y);

function buildBowl(mesh) {
  const prof = [], kinds = [];
  const push = (r, y, k) => { prof.push([r, y]); kinds.push(k); };
  [[0, 0.014], [0.18, 0.014], [0.33, 0.014], [0.345, 0.005], [0.362, 0], [0.385, 0], [0.398, 0.008],
    [0.405, 0.03], [0.404, 0.052], [0.4, 0.065]].forEach(([r, y]) => push(r, y, 0));
  for (let i = 1; i <= 40; i++) { const s = i / 40; push(bowlOuterR(s), 0.065 + 0.675 * s, 0); }
  for (let i = 1; i <= 12; i++) {
    const a = (i / 12) * Math.PI;
    push(0.9825 + 0.0175 * Math.cos(a), RIM_Y + 0.0175 * Math.sin(a), 0.5);
  }
  for (let i = 39; i >= 0; i--) {
    const s = i / 40, y = 0.065 + 0.675 * s;
    if (y < 0.14) break;
    push(bowlOuterR(s) - bowlThick(s), y, 1);
  }
  push(0.25, 0.125, 1); push(0, 0.12, 1);
  lathe(mesh, prof, 180, [0, 0, 0], (k, u) => ({ c: [0, 0, 0], m: [0.1, 0.05, 0, MAT.BOWL], uv: [u, k / (prof.length - 1), kinds[k]] }));
}

function buildBroth(mesh) {
  const R = BROTH_R + 0.012;
  surface(mesh, 128, 12, (u, v) => [R * v * Math.cos(u * TAU), BROTH_Y, R * v * Math.sin(u * TAU)],
    () => ({ c: [0, 0, 0], m: [0, 0, 0, 0], uv: [0, 0, 0] }));
}

function buildTable(mesh) {
  const S = 16, n = [0, 1, 0], a = { c: [0, 0, 0], m: [0, 0, 0, 0], uv: [0, 0, 0] };
  const i0 = mesh.vert([-S, 0, -S], n, a.c, a.m, a.uv);
  mesh.vert([S, 0, -S], n, a.c, a.m, a.uv);
  mesh.vert([S, 0, S], n, a.c, a.m, a.uv);
  mesh.vert([-S, 0, S], n, a.c, a.m, a.uv);
  mesh.quad(i0, i0 + 1, i0 + 2, i0 + 3);
}

// Keeps submerged ends of long pieces inside the bowl wall.
function keepInside(p, rMax) {
  const r = Math.hypot(p[0], p[2]);
  if (r > rMax) { p[0] *= rMax / r; p[2] *= rMax / r; }
  return p;
}

function buildNoodles(mesh, rand) {
  const cx = -0.07, cz = 0.13, ang = -0.40;
  const dir = [Math.cos(ang), Math.sin(ang)], lat = [-Math.sin(ang), Math.cos(ang)];
  const len = 1.16, width = 0.40, NL = 17;
  const strands = [];
  for (let layer = 0; layer < 2; layer++) {
    for (let k = 0; k < NL; k++) {
      const f = (k + (layer ? 0.5 : 0) + (rand() - 0.5) * 0.4) / (NL - 0.5) - 0.5;
      strands.push({
        off: f * width,
        peak: (layer ? 0.062 : 0.04) * (1 - 0.6 * (2 * f) ** 2) + rand() * 0.014,
        ph: rand() * TAU, ph2: rand() * TAU, ph3: rand() * TAU,
        skew: (rand() - 0.5) * 0.1, shift: (rand() - 0.5) * 0.14, lenK: 0.88 + rand() * 0.16,
        tone: rand(),
      });
    }
  }
  // a few loose strands surfacing elsewhere in the broth
  for (let k = 0; k < 7; k++) {
    const a = rand() * TAU, r = 0.25 + rand() * 0.4;
    strands.push({
      loose: true, cx: Math.cos(a) * r, cz: Math.sin(a) * r, a: rand() * Math.PI,
      peak: 0.006 + rand() * 0.012, ph: rand() * TAU, ph2: rand() * TAU, ph3: rand() * TAU, tone: rand(),
    });
  }
  for (const st of strands) {
    const M = st.loose ? 60 : 150, pts = [];
    for (let i = 0; i <= M; i++) {
      const s = i / M;
      let x, z, y;
      if (st.loose) {
        const a = (s - 0.5) * 0.42;
        const d = [Math.cos(st.a), Math.sin(st.a)];
        const wl = 0.007 * Math.sin(a * TAU / 0.05 + st.ph);
        x = st.cx + d[0] * a - d[1] * wl;
        z = st.cz + d[1] * a + d[0] * wl;
        y = BROTH_Y - 0.02 + (0.02 + st.peak) * Math.sin(Math.PI * s) + 0.004 * Math.sin(a * TAU / 0.07 + st.ph3);
      } else {
        const a = (s - 0.5) * len * st.lenK + st.shift;
        const bump = Math.pow(Math.sin(Math.PI * s), 0.7);
        const wl = 0.0072 * Math.sin(a * TAU / 0.052 + st.ph) + 0.0028 * Math.sin(a * TAU / 0.021 + st.ph2);
        const wv = 0.0045 * Math.sin(a * TAU / 0.067 + st.ph3);
        const o = st.off + wl + st.skew * a + 0.1 * (2 * s - 1) ** 2 - 0.03;
        x = cx + dir[0] * a + lat[0] * o;
        z = cz + dir[1] * a + lat[1] * o;
        y = BROTH_Y - 0.045 + (0.045 + st.peak) * bump + wv * bump;
      }
      pts.push(keepInside([x, y, z], 0.84));
    }
    const tone = st.tone;
    const col = [lerp(0.80, 0.90, tone), lerp(0.56, 0.64, tone), lerp(0.19, 0.26, tone)];
    tube(mesh, pts, 0.0088, 7, (t, s) => ({ c: col, m: [0.36, 0.04, 0.5, MAT.NOODLE], uv: [t, s, 0] }));
  }
}

function buildTofu(mesh) {
  const cubes = [
    { c: [0.585, -0.13], s: 0.158, yaw: 0.35, tx: 0.07, tz: -0.10, cut: 2 },
    { c: [0.50, 0.15], s: 0.148, yaw: -0.3, tx: -0.08, tz: 0.13, cut: 1 },
    { c: [0.735, 0.05], s: 0.138, yaw: 0.9, tx: 0.13, tz: 0.06, cut: 3 },
  ];
  for (const cb of cubes) {
    const h = cb.s / 2, hy = h * 0.9;
    const rot = rotMat(cb.yaw, cb.tx, cb.tz);
    roundedBox(mesh, [cb.c[0], BROTH_Y + hy * 0.45, cb.c[1]], [h, hy, h], 0.022, rot, 12,
      (lp) => ({ c: [1, 1, 1], m: [0.45, 0.04, 0.3, MAT.TOFU + cb.cut / 10], uv: [lp[0] / h, lp[1] / hy, lp[2] / h] }));
  }
}

function buildShiitake(mesh, rand) {
  const caps = [
    { c: [0.13, 0.585], R: 0.108, yaw: 0.4, tx: 0.10, tz: 0.07 },
    { c: [0.385, 0.45], R: 0.098, yaw: 1.3, tx: -0.08, tz: 0.12 },
  ];
  for (const cp of caps) {
    const H = cp.R * 0.44, e = 0.011, prof = [], tag = [];
    for (let i = 0; i <= 16; i++) {
      const t = i / 16;
      prof.push([cp.R * t, H * Math.pow(1 - Math.pow(t, 2.4), 0.55)]); tag.push(t);
    }
    for (let i = 1; i <= 7; i++) {
      const a = (i / 7) * Math.PI * 0.95;
      prof.push([cp.R - e + e * Math.cos(a), -e * Math.sin(a) * 0.9]); tag.push(1 + i / 7);
    }
    prof.push([cp.R * 0.55, -0.006]); tag.push(2.5);
    prof.push([0, -0.004]); tag.push(3);
    const rot = rotMat(cp.yaw, cp.tx, cp.tz), spin = rand();
    lathe(mesh, prof, 72, [cp.c[0], BROTH_Y + 0.004, cp.c[1]],
      (k, u) => ({ c: [spin, rand(), 0], m: [0.28, 0.045, 0.2, MAT.SHIITAKE], uv: [u, tag[k], 0] }), rot);
  }
}

function buildBokChoy(mesh) {
  const base = [-0.19, 0.44];
  const leaves = [
    { ang: 2.78, len: 0.50, lift: 0.0, roll: 0.10, cup: 1.0 },
    { ang: 2.36, len: 0.45, lift: 0.014, roll: -0.18, cup: 0.9 },
    { ang: 3.12, len: 0.41, lift: 0.026, roll: 0.24, cup: 0.85 },
  ];
  for (const lf of leaves) {
    const d = [Math.cos(lf.ang), Math.sin(lf.ang)], pr = [-d[1], d[0]];
    const hwAt = (u) => {
      const stalk = u < 0.4 ? lerp(0.027, 0.04, u / 0.4) : 0.04 * (1 - sstep(0.4, 0.95, u));
      const tb = (u - 0.69) / 0.31;
      return Math.max(stalk, 0.09 * Math.sqrt(Math.max(0, 1 - tb * tb)));
    };
    const P = (u, v) => {
      const s = v * 2 - 1, hw = hwAt(u);
      const stalkK = 1 - sstep(0.34, 0.56, u);
      let y = BROTH_Y + lerp(-0.014, 0.004, u) + 0.046 * Math.sin(Math.PI * Math.min(u * 1.05, 1)) * (1 - 0.3 * u);
      y += 0.021 * Math.sqrt(Math.max(0, 1 - s * s)) * stalkK;
      y += lf.cup * 0.02 * s * s * sstep(0.4, 0.75, u);
      y += 0.006 * Math.sin(u * 38 + s * 2.5) * s * s * sstep(0.45, 0.8, u);
      y += s * hw * lf.roll + lf.lift * (1 - 0.6 * u);
      const along = u * lf.len;
      const p = [base[0] + d[0] * along + pr[0] * s * hw, y, base[1] + d[1] * along + pr[1] * s * hw];
      return keepInside(p, 0.9);
    };
    surface(mesh, 40, 12, P, (u, v) => ({ c: [1, 1, 1], m: [0.3, 0.045, 0.45, MAT.BOKCHOY], uv: [u, v * 2 - 1, 0] }));
  }
}

function buildCorn(mesh, rand) {
  const cx = 0.32, cz = -0.47, placed = [];
  const layers = [[0.155, 0.006, 26], [0.11, 0.024, 14], [0.06, 0.04, 6]];
  for (const [R, lift, count] of layers) {
    let tries = 0, n = 0;
    while (n < count && tries++ < 900) {
      const r = Math.sqrt(rand()) * R, a = rand() * TAU;
      const x = cx + r * Math.cos(a), z = cz + r * Math.sin(a);
      if (Math.hypot(x, z) > 0.8) continue;
      if (placed.some((q) => Math.abs(q[1] - lift) < 0.01 && Math.hypot(q[0] - x, q[2] - z) < 0.033)) continue;
      placed.push([x, lift, z]); n++;
      const rot = rotMat(rand() * TAU, (rand() - 0.5) * 0.9, (rand() - 0.5) * 0.9);
      const tone = rand();
      const col = [lerp(0.86, 0.95, tone), lerp(0.50, 0.66, tone), lerp(0.03, 0.09, tone)];
      ellipsoid(mesh, [x, BROTH_Y + lift + 0.01, z], [0.021, 0.015, 0.018], rot, 12, 8,
        (lp) => ({ c: col, m: [0.26, 0.05, 0.45, MAT.CORN], uv: [lp[0] / 0.021, lp[1] / 0.015, lp[2] / 0.018] }), 0.28);
    }
  }
}

function buildNori(mesh) {
  const sheets = [
    { c: [-0.31, -0.6], w: 0.30, h: 0.45, yaw: 0.24, lean: 0.36, curl: 0.035 },
    { c: [-0.01, -0.69], w: 0.31, h: 0.47, yaw: -0.08, lean: 0.31, curl: -0.03 },
  ];
  for (const sh of sheets) {
    const rot = rotMat(sh.yaw, -sh.lean, 0);
    const P = (u, v) => {
      const x = (u - 0.5) * sh.w, y = v * sh.h;
      const z = sh.curl * Math.sin(Math.PI * u) + 0.006 * Math.sin(u * 9 + v * 4) + 0.035 * (1 - v) * (1 - v);
      return vadd([sh.c[0], BROTH_Y - 0.07, sh.c[1]], mapply(rot, [x, y, z]));
    };
    surface(mesh, 12, 16, P, (u, v) => ({ c: [1, 1, 1], m: [0.4, 0.05, 0.1, MAT.NORI], uv: [u, v, 0] }));
  }
}

function buildMenma(mesh, rand) {
  const base = [-0.53, -0.25], ax = 0.75;
  for (let i = 0; i < 5; i++) {
    const L = 0.16 + rand() * 0.04, W = 0.036 + rand() * 0.01, T = 0.016;
    const off = (i - 2) * 0.034;
    const c = [base[0] - Math.sin(ax) * off + (rand() - 0.5) * 0.02, BROTH_Y + 0.004 + (i % 2) * 0.012, base[1] + Math.cos(ax) * off + (rand() - 0.5) * 0.02];
    const rot = rotMat(ax + (rand() - 0.5) * 0.35, (rand() - 0.5) * 0.2, (i % 2 ? 1 : -1) * 0.12);
    keepInside(c, 0.74);
    roundedBox(mesh, c, [L / 2, T / 2, W / 2], 0.006, rot, 6,
      (lp) => ({ c: [1, 1, 1], m: [0.3, 0.045, 0.35, MAT.MENMA], uv: [lp[0] / (L / 2), lp[1] / (T / 2), lp[2] / (W / 2)] }));
  }
}

// Small garnishes are dropped onto the heightfield of what is already in the bowl.
function surfaceTilt(H, x, z, e) {
  const sx = (H(x + e, z) - H(x - e, z)) / (2 * e), sz = (H(x, z + e) - H(x, z - e)) / (2 * e);
  return [Math.atan(sx), -Math.atan(sz)];
}

function buildScallions(mesh, rand, H) {
  for (let n = 0; n < 70; n++) {
    let x, z;
    if (n < 44) {
      const r = Math.sqrt(rand()) * 0.25, a = rand() * TAU;
      x = -0.05 + r * Math.cos(a) * 1.25; z = 0.11 + r * Math.sin(a) * 0.85;
    } else {
      const r = 0.15 + Math.sqrt(rand()) * 0.66, a = rand() * TAU;
      x = r * Math.cos(a); z = r * Math.sin(a);
    }
    if (Math.hypot(x, z) > 0.82) continue;
    const ro = 0.019 + rand() * 0.009, ri = ro * (0.6 + rand() * 0.12), hh = 0.0042 + rand() * 0.0022;
    const hmax = Math.max(H(x, z), H(x + ro, z), H(x - ro, z), H(x, z + ro), H(x, z - ro));
    const [roll, pitch] = surfaceTilt(H, x, z, 0.02);
    const rot = rotMat(0, pitch * 0.8 + (rand() - 0.5) * 0.6, roll * 0.8 + (rand() - 0.5) * 0.6);
    const white = rand() < 0.22 ? 1 : 0, tone = rand();
    ringSlice(mesh, [x, hmax + hh * 0.6, z], ro, ri, hh, rot, 14,
      (kind, radial) => ({ c: [white, tone, 0], m: [0.3, 0.045, 0.5, MAT.SCALLION], uv: [radial, radial, kind] }));
  }
}

function buildSesame(mesh, rand, H) {
  for (let n = 0; n < 110; n++) {
    let x, z;
    if (n < 50) {
      const r = Math.sqrt(rand()) * 0.3, a = rand() * TAU;
      x = -0.02 + r * Math.cos(a) * 1.3; z = 0.08 + r * Math.sin(a);
    } else {
      const r = Math.sqrt(rand()) * 0.8, a = rand() * TAU;
      x = r * Math.cos(a); z = r * Math.sin(a);
    }
    const [roll, pitch] = surfaceTilt(H, x, z, 0.01);
    const rot = rotMat(rand() * TAU, pitch + (rand() - 0.5) * 0.3, roll + (rand() - 0.5) * 0.3);
    const black = rand() < 0.16;
    const col = black ? [0.03, 0.025, 0.022] : [0.80, 0.66, 0.44];
    ellipsoid(mesh, [x, H(x, z) + 0.0025, z], [0.0115, 0.0032, 0.0072], rot, 10, 6,
      () => ({ c: col, m: [black ? 0.25 : 0.4, 0.045, 0.3, MAT.SESAME], uv: [0, 0, 0] }), 0.4);
  }
}

function buildChili(mesh, rand, H) {
  for (let n = 0; n < 18; n++) {
    let x = 0.0 + (rand() - 0.5) * 0.16, z = 0.1 + (rand() - 0.5) * 0.12;
    let a = rand() * TAU;
    const turn = (rand() - 0.5) * 0.28, L = 0.1 + rand() * 0.11, steps = 44, ds = L / steps, pts = [];
    for (let i = 0; i <= steps; i++) {
      pts.push([x, H(x, z) + 0.0042 + 0.005 * Math.sin((i / steps) * Math.PI), z]);
      a += turn + (rand() - 0.5) * 0.35;
      x += Math.cos(a) * ds; z += Math.sin(a) * ds;
    }
    const tone = rand();
    tube(mesh, pts, 0.0023, 5, () => ({ c: [tone, 0, 0], m: [0.3, 0.045, 0.6, MAT.CHILI], uv: [0, 0, 0] }));
  }
}

// ---------------------------------------------------------------------------
// Shaders (GLSL ES 3.00)
// ---------------------------------------------------------------------------
const VS_SCENE = `#version 300 es
layout(location=0) in vec3 aPos;
layout(location=1) in vec3 aNrm;
layout(location=2) in vec3 aCol;
layout(location=3) in vec4 aMat;
layout(location=4) in vec3 aUV;
layout(location=5) in vec2 aBake;
uniform mat4 uViewProj;
out vec3 vPos; out vec3 vNrm; out vec3 vCol; out vec4 vMat; out vec3 vUV; out vec2 vBake;
void main() {
  vPos = aPos; vNrm = aNrm; vCol = aCol; vMat = aMat; vUV = aUV; vBake = aBake;
  gl_Position = uViewProj * vec4(aPos, 1.0);
}`;

const VS_FULL = `#version 300 es
out vec2 vUV;
void main() {
  vec2 p = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2));
  vUV = p;
  gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);
}`;

const FS_HEAD = `#version 300 es
precision highp float;
precision highp int;
precision highp sampler3D;
#define PI 3.14159265
float hash12(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * .1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }
vec2 hash22(vec2 p) { vec3 p3 = fract(vec3(p.xyx) * vec3(.1031, .1030, .0973)); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.xx + p3.yz) * p3.zy); }
float hash13(vec3 p3) { p3 = fract(p3 * .1031); p3 += dot(p3, p3.zyx + 31.32); return fract((p3.x + p3.y) * p3.z); }
float vnoise(vec2 p) {
  vec2 i = floor(p), f = fract(p), u = f * f * (3. - 2. * f);
  return mix(mix(hash12(i), hash12(i + vec2(1, 0)), u.x), mix(hash12(i + vec2(0, 1)), hash12(i + vec2(1, 1)), u.x), u.y);
}
float vnoise3(vec3 p) {
  vec3 i = floor(p), f = fract(p), u = f * f * (3. - 2. * f);
  return mix(mix(mix(hash13(i), hash13(i + vec3(1, 0, 0)), u.x), mix(hash13(i + vec3(0, 1, 0)), hash13(i + vec3(1, 1, 0)), u.x), u.y),
             mix(mix(hash13(i + vec3(0, 0, 1)), hash13(i + vec3(1, 0, 1)), u.x), mix(hash13(i + vec3(0, 1, 1)), hash13(i + vec3(1, 1, 1)), u.x), u.y), u.z);
}
float fbm2(vec2 p) {
  float s = 0., a = .5;
  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = mat2(1.6, 1.2, -1.2, 1.6) * p + 7.13; a *= .5; }
  return s;
}
vec3 aces(vec3 x) { return clamp((x * (2.51 * x + .03)) / (x * (2.43 * x + .59) + .14), 0., 1.); }
`;

// Lighting shared by every surface of the dish.
const FS_LIGHT = `
uniform vec3 uCamPos, uLightPos, uLightCol, uFillDir, uFillCol;
uniform float uTime, uExposure, uBrothY;
float D_GGX(float NoH, float a) { float a2 = a * a; float d = NoH * NoH * (a2 - 1.) + 1.; return a2 / (PI * d * d); }
float V_Smith(float NoV, float NoL, float a) { float k = a * .5; return .25 / max((NoV * (1. - k) + k) * (NoL * (1. - k) + k), 1e-4); }
float F_Schlick(float f0, float c) { return f0 + (1. - f0) * pow(1. - c, 5.); }
vec3 keyLight(vec3 P, out vec3 L) {
  vec3 Lv = uLightPos - P; float d = length(Lv); L = Lv / d;
  float d0 = length(uLightPos - vec3(0., .6, 0.));
  vec3 spotDir = normalize(vec3(0., .45, 0.) - uLightPos);
  float cone = smoothstep(.78, .975, dot(-L, spotDir));
  return uLightCol * (d0 * d0) / (d * d) * cone;
}
vec3 envRefl(vec3 R, float rough) {
  vec3 Ld = normalize(uLightPos - vec3(0., .6, 0.));
  float r2 = rough * rough;
  float s = .12 + r2 * 1.5;
  float lamp = exp((dot(R, Ld) - 1.) / (s * s)) / (1. + 14. * r2);
  float s2 = .35 + r2;
  float card = exp((dot(R, uFillDir) - 1.) / (s2 * s2)) / (1. + 6. * r2);
  vec3 room = mix(vec3(.028, .018, .012), vec3(.008, .007, .008), smoothstep(-.3, .7, R.y));
  return uLightCol * lamp * .55 + uFillCol * card * 1.6 + room;
}
vec3 ambient(vec3 N) {
  float f = clamp(dot(N, uFillDir) * .5 + .5, 0., 1.);
  return uFillCol * f * f + mix(vec3(.042, .026, .015), vec3(.024, .024, .029), N.y * .5 + .5);
}
vec4 finish(vec3 lin) {
  float lum = dot(lin, vec3(.2126, .7152, .0722)) * uExposure;
  float bloom = clamp((lum - .8) * .4, 0., 1.);
  vec3 c = pow(aces(lin * uExposure), vec3(1. / 2.2));
  c += (hash12(gl_FragCoord.xy + fract(uTime * 7.31) * 97.) - .5) / 255.;
  return vec4(c, bloom);
}
`;

const FS_SCENE = FS_HEAD + FS_LIGHT + `
in vec3 vPos; in vec3 vNrm; in vec3 vCol; in vec4 vMat; in vec3 vUV; in vec2 vBake;
out vec4 fragColor;
void main() {
  vec3 P = vPos, N = normalize(vNrm), V = normalize(uCamPos - P);
  vec3 alb = vCol, sss = vec3(0.);
  float rough = vMat.x, f0 = vMat.y, wrap = vMat.z, specK = 1.;
  int id = int(floor(vMat.w + .02));
  float sub = floor(fract(vMat.w + .02) * 10. + .1);
  float ao = vBake.x, sh = vBake.y;
  bool twoSided = false;

  if (id == 1) {                       // tenmoku-glazed bowl
    float ang = atan(P.z, P.x), y = P.y, side = vUV.z;
    float st = vnoise(vec2(ang * 46., y * 2.2)) * .6 + vnoise(vec2(ang * 130., y * 5.)) * .4;
    float streak = smoothstep(.52, .86, st) * smoothstep(.12, .62, y);
    alb = mix(vec3(.010, .008, .007), vec3(.16, .06, .02), streak * .8);
    alb = mix(alb, vec3(.30, .14, .05), smoothstep(.70, .75, y) * .85);
    rough = .08 + .06 * vnoise(vec2(ang * 9., y * 14.));
    f0 = .045; wrap = 0.;
    if (side < .25) {
      float foot = 1. - smoothstep(.05, .08, y);
      alb = mix(alb, vec3(.26, .17, .11), foot);
      rough = mix(rough, .8, foot);
    }
    if (side > .75) {
      float wet = 1. - smoothstep(uBrothY - .002, uBrothY + .022, y);
      alb = mix(alb, vec3(.40, .17, .04), wet * .55);
      rough = mix(rough, .05, wet);
    }
    vec2 gn = vec2(vnoise(vec2(ang * 34., y * 22.)), vnoise(vec2(ang * 34. + 7., y * 22. + 3.))) - .5;
    N = normalize(N + vec3(gn.x, 0., gn.y) * .03);
  } else if (id == 2) {                // noodles
    float wet = 1. - smoothstep(uBrothY - .004, uBrothY + .03, P.y);
    alb *= mix(vec3(1.), vec3(.93, .74, .5), wet * .8);
    alb *= .94 + .12 * vnoise(vec2(vUV.x * 180., vUV.y * 3.));
    rough = mix(.36, .2, wet);
    sss = alb * vec3(.55, .40, .18);
  } else if (id == 3) {                // fried tofu
    vec3 q = vUV, aq = abs(q);
    float face = (aq.x >= aq.y && aq.x >= aq.z) ? 1. : ((aq.y >= aq.z) ? 2. : 3.);
    float second = max(min(aq.x, aq.y), min(max(aq.x, aq.y), aq.z));
    float edge = smoothstep(.70, .97, second);
    vec3 lp = q * 3.2 + sub * 7.1;
    float n1 = vnoise3(lp * 2.3), n2 = vnoise3(lp * 6.1 + 3.), n3 = vnoise3(lp * 16. + 9.);
    vec3 golden = vec3(.66, .34, .09);
    vec3 crust = mix(golden, vec3(.85, .55, .22), smoothstep(.45, .85, n1) * .7);
    crust = mix(crust, vec3(.30, .12, .03), clamp(smoothstep(.55, .9, n2) * .5 + edge * .35, 0., 1.));
    alb = crust * (.88 + .24 * n3);
    rough = .5 - .15 * n2; sss = vec3(.30, .14, .04);
    if (abs(face - sub) < .5) {
      vec3 cream = vec3(.82, .72, .52);
      alb = mix(cream, cream * vec3(.86, .82, .74), smoothstep(.55, .85, vnoise3(lp * 14.)));
      vec3 aq2 = aq;
      if (face == 1.) aq2.x = 0.; else if (face == 2.) aq2.y = 0.; else aq2.z = 0.;
      alb = mix(alb, golden * .9, smoothstep(.84, .95, max(aq2.x, max(aq2.y, aq2.z))));
      rough = .65; sss = vec3(.5, .45, .36);
    }
  } else if (id == 4) {                // simmered shiitake with a star cut
    float ang = vUV.x * 6.2831853 + vCol.x * 6.2831853, t = vUV.y;
    if (t <= 1.) {
      float cut = 0.;
