  for (int i = 0; i < 6; i++) {
    vec4 b = uBokeh[i];
    float r = length((uv - b.xy) * vec2(aspect, 1.)) / b.z;
    float disk = 1. - smoothstep(.9, 1., r);
    bk += uBokehC[i] * b.w * disk * (.65 + .35 * smoothstep(.55, .95, r));
  }
  vec4 st = texture(uSteam, uv);
  col = col * (1. - st.a) + st.rgb + bk * (1. - st.a);
  col += texture(uBloom, uv).rgb * uBloomK;
  vec2 vv = dc * vec2(aspect, 1.) / max(aspect, 1.);
  float vig = smoothstep(.95, .2, length(vv * vec2(1., 1.15)));
  col *= mix(.3, 1., vig);
  col += (hash12(gl_FragCoord.xy + fract(uTime * 13.7) * vec2(211., 137.)) - .5) * .022;
  fragColor = vec4(max(col, 0.), 1.);
}`;

// ---------------------------------------------------------------------------
// WebGL2 plumbing
// ---------------------------------------------------------------------------
const gl = canvas.getContext('webgl2', {
  antialias: false, alpha: false, depth: false, stencil: false,
  premultipliedAlpha: false, preserveDrawingBuffer: false, powerPreference: 'default',
});

function compileShader(type, src) {
  const s = gl.createShader(type);
  gl.shaderSource(s, src);
  gl.compileShader(s);
  if (!gl.getShaderParameter(s, gl.COMPILE_STATUS) && !gl.isContextLost()) {
    throw new Error('Shader compile failed: ' + gl.getShaderInfoLog(s));
  }
  return s;
}

function makeProgram(vs, fs) {
  const p = gl.createProgram();
  gl.attachShader(p, compileShader(gl.VERTEX_SHADER, vs));
  gl.attachShader(p, compileShader(gl.FRAGMENT_SHADER, fs));
  gl.linkProgram(p);
  if (!gl.getProgramParameter(p, gl.LINK_STATUS) && !gl.isContextLost()) {
    throw new Error('Program link failed: ' + gl.getProgramInfoLog(p));
  }
  const u = {};
  const n = gl.getProgramParameter(p, gl.ACTIVE_UNIFORMS) || 0;
  for (let i = 0; i < n; i++) {
    const info = gl.getActiveUniform(p, i);
    u[info.name.replace(/\[0\]$/, '')] = gl.getUniformLocation(p, info.name);
  }
  return { p, u };
}

function uploadMesh(mesh, old) {
  if (old) { gl.deleteVertexArray(old.vao); gl.deleteBuffer(old.vbo); gl.deleteBuffer(old.ibo); }
  const vao = gl.createVertexArray();
  gl.bindVertexArray(vao);
  const vbo = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(mesh.data), gl.STATIC_DRAW);
  let off = 0;
  [3, 3, 3, 4, 3, 2].forEach((size, i) => {
    gl.enableVertexAttribArray(i);
    gl.vertexAttribPointer(i, size, gl.FLOAT, false, STRIDE * 4, off * 4);
    off += size;
  });
  const ibo = gl.createBuffer();
  gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, ibo);
  gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, new Uint32Array(mesh.index), gl.STATIC_DRAW);
  gl.bindVertexArray(null);
  return { vao, vbo, ibo, count: mesh.index.length };
}

function drawMesh(m) {
  gl.bindVertexArray(m.vao);
  gl.drawElements(gl.TRIANGLES, m.count, gl.UNSIGNED_INT, 0);
}

function makeTex(w, h, ifmt, fmt, type, filter, wrap, data = null) {
  const t = gl.createTexture();
  gl.bindTexture(gl.TEXTURE_2D, t);
  gl.texImage2D(gl.TEXTURE_2D, 0, ifmt, w, h, 0, fmt, type, data);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, filter);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, filter);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, wrap);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, wrap);
  return t;
}

// Colour render target (RGBA8), optionally with a depth renderbuffer.
function makeTarget(w, h, withDepth = false, filter = gl.LINEAR) {
  const tex = makeTex(w, h, gl.RGBA8, gl.RGBA, gl.UNSIGNED_BYTE, filter, gl.CLAMP_TO_EDGE);
  const fb = gl.createFramebuffer();
  gl.bindFramebuffer(gl.FRAMEBUFFER, fb);
  gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, tex, 0);
  let depth = null;
  if (withDepth) {
    depth = gl.createRenderbuffer();
    gl.bindRenderbuffer(gl.RENDERBUFFER, depth);
    gl.renderbufferStorage(gl.RENDERBUFFER, gl.DEPTH_COMPONENT24, w, h);
    gl.framebufferRenderbuffer(gl.FRAMEBUFFER, gl.DEPTH_ATTACHMENT, gl.RENDERBUFFER, depth);
  }
  gl.bindFramebuffer(gl.FRAMEBUFFER, null);
  return { tex, fb, depth, w, h };
}

function freeTarget(t) {
  if (!t) return;
  if (t.tex) gl.deleteTexture(t.tex);
  if (t.fb) gl.deleteFramebuffer(t.fb);
  if (t.depth) gl.deleteRenderbuffer(t.depth);
  if (t.color) gl.deleteRenderbuffer(t.color);
}

// Multisampled colour + depth, resolved by blitting into a texture target.
function makeMSTarget(w, h, samples) {
  const fb = gl.createFramebuffer();
  gl.bindFramebuffer(gl.FRAMEBUFFER, fb);
  const color = gl.createRenderbuffer();
  gl.bindRenderbuffer(gl.RENDERBUFFER, color);
  gl.renderbufferStorageMultisample(gl.RENDERBUFFER, samples, gl.RGBA8, w, h);
  gl.framebufferRenderbuffer(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.RENDERBUFFER, color);
  const depth = gl.createRenderbuffer();
  gl.bindRenderbuffer(gl.RENDERBUFFER, depth);
  gl.renderbufferStorageMultisample(gl.RENDERBUFFER, samples, gl.DEPTH_COMPONENT24, w, h);
  gl.framebufferRenderbuffer(gl.FRAMEBUFFER, gl.DEPTH_ATTACHMENT, gl.RENDERBUFFER, depth);
  const ok = gl.checkFramebufferStatus(gl.FRAMEBUFFER) === gl.FRAMEBUFFER_COMPLETE;
  gl.bindFramebuffer(gl.FRAMEBUFFER, null);
  const t = { fb, color, depth, w, h };
  if (!ok) { freeTarget(t); return null; }
  return t;
}

function drawFull() {
  gl.bindVertexArray(emptyVAO);
  gl.drawArrays(gl.TRIANGLES, 0, 3);
}

// Orthographic top-down projection used for the heightfield: x -> clip x, z -> clip y, higher y -> nearer.
const TOPDOWN = new Float32Array([1 / H_EXT, 0, 0, 0, 0, 0, -1 / 0.9, 0, 0, 1 / H_EXT, 0, 0, 0, 0, 0.8 / 0.9, 1]);

function sampler(H) {
  return (x, z) => {
    const fx = (x / H_EXT * 0.5 + 0.5) * H_RES - 0.5, fz = (z / H_EXT * 0.5 + 0.5) * H_RES - 0.5;
    const ix = Math.floor(fx), iz = Math.floor(fz);
    if (ix < 0 || iz < 0 || ix >= H_RES - 1 || iz >= H_RES - 1) return 0;
    const tx = fx - ix, tz = fz - iz, i = iz * H_RES + ix;
    return (H[i] * (1 - tx) + H[i + 1] * tx) * (1 - tz) + (H[i + H_RES] * (1 - tx) + H[i + H_RES + 1] * tx) * tz;
  };
}

// Render everything in the bowl from above and read the heights back.
function heightPass(prog, target, meshes) {
  gl.bindFramebuffer(gl.FRAMEBUFFER, target.fb);
  gl.viewport(0, 0, H_RES, H_RES);
  gl.clearColor(0, 0, 0, 0);
  gl.clearDepth(1);
  gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
  gl.enable(gl.DEPTH_TEST);
  gl.depthFunc(gl.LESS);
  gl.useProgram(prog.p);
  gl.uniformMatrix4fv(prog.u.uViewProj, false, TOPDOWN);
  meshes.forEach(drawMesh);
  const px = new Uint8Array(H_RES * H_RES * 4);
  gl.readPixels(0, 0, H_RES, H_RES, gl.RGBA, gl.UNSIGNED_BYTE, px);
  gl.bindFramebuffer(gl.FRAMEBUFFER, null);
  const H = new Float32Array(H_RES * H_RES);
  for (let i = 0; i < H.length; i++) H[i] = ((px[i * 4] * 256 + px[i * 4 + 1]) / 65535) * H_MAX;
  return H;
}

// Per-vertex ambient occlusion and soft key-light shadow from the heightfield.
function bakeMesh(mesh, Hs) {
  const d = mesh.data, lp = LIGHT_POS, tanL = 0.16;
  const dirs = [];
  for (let k = 0; k < 10; k++) { const a = k * 2.39996 + 0.4; dirs.push([Math.cos(a), Math.sin(a)]); }
  const radii = [0.02, 0.05, 0.1, 0.18];
  for (let v = 0; v < mesh.count; v++) {
    const o = v * STRIDE;
    const px = d[o], py = d[o + 1], pz = d[o + 2], nx = d[o + 3], ny = d[o + 4], nz = d[o + 5];
    const id = Math.floor(d[o + 12] + 0.02), side = d[o + 15];
    if (id === MAT.BOWL && side < 0.25) {
      d[o + 16] = lerp(0.3, 1, sstep(0.0, 0.32, py));
      d[o + 17] = 1;
      continue;
    }
    // ambient occlusion: horizon angles in a few directions, weighted toward the normal
    const ox = px + nx * 0.01, oy = py + ny * 0.01, oz = pz + nz * 0.01;
    let occ = 0, wsum = 0;
    for (const [dx, dz] of dirs) {
      const w = Math.max(0.05, 0.35 + 0.65 * Math.max(ny, 0) + dx * nx + dz * nz);
      let mt = 0;
      for (const r of radii) mt = Math.max(mt, (Hs(ox + dx * r, oz + dz * r) - oy) / r);
      occ += w * (mt / Math.sqrt(1 + mt * mt));
      wsum += w;
    }
    let ao = 1 - occ / wsum;
    if (oy < Hs(ox, oz) - 0.006) ao *= 0.3;
    // soft shadow toward the lamp
    let lx = lp[0] - ox, ly = lp[1] - oy, lz = lp[2] - oz;
    const ll = Math.hypot(lx, ly, lz); lx /= ll; ly /= ll; lz /= ll;
    let sh = 1, t = 0.008;
    for (let i = 0; i < 44; i++) {
      const qx = ox + lx * t, qy = oy + ly * t, qz = oz + lz * t;
      if (qy > 1.25) break;
      const dh = qy - Hs(qx, qz);
      sh = Math.min(sh, 0.5 + dh / (2 * t * tanL));
      if (sh <= 0) { sh = 0; break; }
      t += 0.006 + t * 0.04;
    }
    d[o + 16] = clamp(ao, 0.04, 1);
    d[o + 17] = clamp(sh, 0, 1);
  }
}

// ---------------------------------------------------------------------------
// Steam interaction: a small CPU fluid solver in the vertical plane through
// the bowl. It stores how far the air has pushed the steam (a displacement
// field) plus how much clear air was mixed in; the steam shader reads both.
// ---------------------------------------------------------------------------
const SIM_NX = 56, SIM_NY = 36, SIM_CELL = 5.0 / SIM_NX, SIM_X0 = -2.5, SIM_Y0 = 0.4;
const SIM_N = SIM_NX * SIM_NY, DISP_MAX = 0.7, RISE = 0.3;
const sU = new Float32Array(SIM_N), sV = new Float32Array(SIM_N), sU2 = new Float32Array(SIM_N), sV2 = new Float32Array(SIM_N);
const sP = new Float32Array(SIM_N), sDiv = new Float32Array(SIM_N), sCurl = new Float32Array(SIM_N);
const sDX = new Float32Array(SIM_N), sDY = new Float32Array(SIM_N), sC = new Float32Array(SIM_N);
const sDX2 = new Float32Array(SIM_N), sDY2 = new Float32Array(SIM_N), sC2 = new Float32Array(SIM_N);
const simBytes = new Uint8Array(SIM_N * 4);
let simActive = false, simDirty = true;

function simClear() {
  [sU, sV, sDX, sDY, sC].forEach((a) => a.fill(0));
  simActive = false; simDirty = true;
}
function bilerp(f, gx, gy) {
  gx = clamp(gx, 0, SIM_NX - 1.001); gy = clamp(gy, 0, SIM_NY - 1.001);
  const ix = gx | 0, iy = gy | 0, tx = gx - ix, ty = gy - iy, i = iy * SIM_NX + ix;
  return (f[i] * (1 - tx) + f[i + 1] * tx) * (1 - ty) + (f[i + SIM_NX] * (1 - tx) + f[i + SIM_NX + 1] * tx) * ty;
}
const riseAt = (j) => {
  const h = Math.max(0, SIM_Y0 + (j + 0.5) * SIM_CELL - BROTH_Y);
  return RISE / Math.max(0.3, 1 - 0.24 * h);
};
function advect(dst, src, dt) {
  const k0 = dt / SIM_CELL;
  for (let j = 0; j < SIM_NY; j++) {
    const rise = riseAt(j);
    for (let i = 0; i < SIM_NX; i++) {
      const k = j * SIM_NX + i;
      dst[k] = bilerp(src, i - sU[k] * k0, j - (sV[k] + rise) * k0);
    }
  }
}
function splat(wx, wy, fx, fy, radius, dilute, radial = 0) {
  const gx = (wx - SIM_X0) / SIM_CELL - 0.5, gy = (wy - SIM_Y0) / SIM_CELL - 0.5;
  const rr = radius / SIM_CELL, R = Math.ceil(rr * 2.5);
  for (let j = Math.max(0, Math.floor(gy - R)); j <= Math.min(SIM_NY - 1, Math.ceil(gy + R)); j++) {
    for (let i = Math.max(0, Math.floor(gx - R)); i <= Math.min(SIM_NX - 1, Math.ceil(gx + R)); i++) {
      const dx = i - gx, dy = j - gy, d2 = dx * dx + dy * dy, w = Math.exp(-d2 / (rr * rr)), k = j * SIM_NX + i;
      const dl = Math.sqrt(d2) + 1e-4;
      sU[k] += (fx + radial * dx / dl) * w;
      sV[k] += (fy + radial * dy / dl) * w;
      sC[k] = Math.min(1, sC[k] + dilute * w);
    }
  }
  simActive = true;
}
function simStep(dt) {
  if (!simActive) return;
  const NX = SIM_NX;
  // vorticity confinement keeps the eddies curling
  for (let j = 1; j < SIM_NY - 1; j++) {
    for (let i = 1; i < NX - 1; i++) {
      const k = j * NX + i;
      sCurl[k] = 0.5 * ((sV[k + 1] - sV[k - 1]) - (sU[k + NX] - sU[k - NX]));
    }
  }
  for (let j = 2; j < SIM_NY - 2; j++) {
    for (let i = 2; i < NX - 2; i++) {
      const k = j * NX + i;
      const gx = 0.5 * (Math.abs(sCurl[k + 1]) - Math.abs(sCurl[k - 1]));
      const gy = 0.5 * (Math.abs(sCurl[k + NX]) - Math.abs(sCurl[k - NX]));
      const l = Math.hypot(gx, gy) + 1e-5, w = sCurl[k] * 2.2 * dt;
      sU[k] += (gy / l) * w;
      sV[k] -= (gx / l) * w;
    }
  }
  // pressure projection (open boundaries)
  sP.fill(0);
  for (let j = 1; j < SIM_NY - 1; j++) {
    for (let i = 1; i < NX - 1; i++) {
      const k = j * NX + i;
      sDiv[k] = -0.5 * (sU[k + 1] - sU[k - 1] + sV[k + NX] - sV[k - NX]);
    }
  }
  for (let it = 0; it < 18; it++) {
    for (let j = 1; j < SIM_NY - 1; j++) {
      for (let i = 1; i < NX - 1; i++) {
        const k = j * NX + i;
        sP[k] = (sDiv[k] + sP[k - 1] + sP[k + 1] + sP[k - NX] + sP[k + NX]) * 0.25;
      }
    }
  }
  for (let j = 1; j < SIM_NY - 1; j++) {
    for (let i = 1; i < NX - 1; i++) {
      const k = j * NX + i;
      sU[k] -= 0.5 * (sP[k + 1] - sP[k - 1]);
      sV[k] -= 0.5 * (sP[k + NX] - sP[k - NX]);
    }
  }
  advect(sU2, sU, dt); advect(sV2, sV, dt);
  advect(sDX2, sDX, dt); advect(sDY2, sDY, dt); advect(sC2, sC, dt);
  const damp = Math.exp(-dt * 1.3), relax = Math.exp(-dt * 0.45), fade = Math.exp(-dt * 0.7);
  let peak = 0;
  for (let k = 0; k < SIM_N; k++) {
    const u = sU2[k] * damp, v = sV2[k] * damp;
    sU[k] = u; sV[k] = v;
    let dx = sDX2[k] * relax + u * dt, dy = sDY2[k] * relax + v * dt;
    const m = Math.hypot(dx, dy);
    if (m > DISP_MAX) { dx *= DISP_MAX / m; dy *= DISP_MAX / m; }
    sDX[k] = dx; sDY[k] = dy; sC[k] = sC2[k] * fade;
    peak = Math.max(peak, m, sC[k], Math.abs(u) * 0.1, Math.abs(v) * 0.1);
  }
  if (peak < 1e-3) simClear();
  simDirty = true;
}
function simUpload() {
  if (!simDirty) return;
  for (let k = 0; k < SIM_N; k++) {
    simBytes[k * 4] = clamp(Math.round(127.5 + (sDX[k] / DISP_MAX) * 127.5), 0, 255);
    simBytes[k * 4 + 1] = clamp(Math.round(127.5 + (sDY[k] / DISP_MAX) * 127.5), 0, 255);
    simBytes[k * 4 + 2] = clamp(Math.round(sC[k] * 255), 0, 255);
    simBytes[k * 4 + 3] = 255;
  }
  gl.bindTexture(gl.TEXTURE_2D, simTex);
  gl.texSubImage2D(gl.TEXTURE_2D, 0, 0, 0, SIM_NX, SIM_NY, gl.RGBA, gl.UNSIGNED_BYTE, simBytes);
  simDirty = false;
}

// ---------------------------------------------------------------------------
// Scene setup
// ---------------------------------------------------------------------------
const prog = {};
let emptyVAO = null, meshes = null, texH = null, lightRT = null, noiseTex = null, simTex = null;
let cpu = null;
const NOISE_N = 64;

function buildScene() {
  const rand = mulberry32(0x5eed2026);
  const bowl = new Mesh(), broth = new Mesh(), table = new Mesh(), food = new Mesh();
  buildBowl(bowl); buildBroth(broth); buildTable(table);
  buildNoodles(food, rand); buildTofu(food); buildShiitake(food, rand); buildBokChoy(food);
  buildCorn(food, rand); buildNori(food); buildMenma(food, rand);
  const rt = makeTarget(H_RES, H_RES, true, gl.NEAREST);
  const g = { bowl: uploadMesh(bowl), broth: uploadMesh(broth), food: uploadMesh(food) };
  const pass = () => sampler(heightPass(prog.height, rt, [g.bowl, g.broth, g.food]));
  let Hs = pass();
  buildScallions(food, rand, Hs); buildSesame(food, rand, Hs);
  g.food = uploadMesh(food, g.food);
  Hs = pass();
  buildChili(food, rand, Hs);
  g.food = uploadMesh(food, g.food);
  const H = heightPass(prog.height, rt, [g.bowl, g.broth, g.food]);
  Hs = sampler(H);
  bakeMesh(bowl, Hs); bakeMesh(food, Hs);
  Object.values(g).forEach((m) => { gl.deleteVertexArray(m.vao); gl.deleteBuffer(m.vbo); gl.deleteBuffer(m.ibo); });
  freeTarget(rt);
  for (const m of [bowl, broth, table, food]) { m.data = new Float32Array(m.data); m.index = new Uint32Array(m.index); }
  return { bowl, broth, table, food, H };
}

function setupGL() {
  emptyVAO = gl.createVertexArray();
  prog.scene = makeProgram(VS_SCENE, FS_SCENE);
  prog.broth = makeProgram(VS_SCENE, FS_BROTH);
  prog.table = makeProgram(VS_SCENE, FS_TABLE);
  prog.height = makeProgram(VS_SCENE, FS_HEIGHT);
  prog.lightmap = makeProgram(VS_FULL, FS_LIGHTMAP);
  prog.noise = makeProgram(VS_FULL, FS_NOISE3D);
  prog.steam = makeProgram(VS_FULL, FS_STEAM);
  prog.down = makeProgram(VS_FULL, FS_BLOOM_DOWN);
  prog.blur = makeProgram(VS_FULL, FS_BLUR);
  prog.final = makeProgram(VS_FULL, FS_FINAL);
  if (!cpu) cpu = buildScene();
  meshes = { bowl: uploadMesh(cpu.bowl), broth: uploadMesh(cpu.broth), table: uploadMesh(cpu.table), food: uploadMesh(cpu.food) };
  texH = makeTex(H_RES, H_RES, gl.R16F, gl.RED, gl.FLOAT, gl.LINEAR, gl.CLAMP_TO_EDGE, cpu.H);

  // soft shadows + occlusion for the broth and the table, seen from above
  lightRT = makeTarget(LM_RES, LM_RES, false, gl.LINEAR);
  gl.bindFramebuffer(gl.FRAMEBUFFER, lightRT.fb);
  gl.viewport(0, 0, LM_RES, LM_RES);
  gl.disable(gl.DEPTH_TEST); gl.disable(gl.BLEND);
  const lm = prog.lightmap;
  gl.useProgram(lm.p);
  gl.activeTexture(gl.TEXTURE0); gl.bindTexture(gl.TEXTURE_2D, texH);
  gl.uniform1i(lm.u.uH, 0);
  gl.uniform1f(lm.u.uHExt, H_EXT); gl.uniform1f(lm.u.uLMExt, LM_EXT); gl.uniform1f(lm.u.uLightRad, LIGHT_RAD);
  gl.uniform3fv(lm.u.uLightPos, LIGHT_POS);
  drawFull();

  // tileable 3D noise for the steam
  noiseTex = gl.createTexture();
  gl.bindTexture(gl.TEXTURE_3D, noiseTex);
  gl.texImage3D(gl.TEXTURE_3D, 0, gl.RGBA8, NOISE_N, NOISE_N, NOISE_N, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
  gl.texParameteri(gl.TEXTURE_3D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_3D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  [gl.TEXTURE_WRAP_S, gl.TEXTURE_WRAP_T, gl.TEXTURE_WRAP_R].forEach((w) => gl.texParameteri(gl.TEXTURE_3D, w, gl.REPEAT));
  const fb = gl.createFramebuffer();
  gl.bindFramebuffer(gl.FRAMEBUFFER, fb);
  gl.viewport(0, 0, NOISE_N, NOISE_N);
  gl.useProgram(prog.noise.p);
  gl.uniform1f(prog.noise.u.uSize, NOISE_N);
  for (let z = 0; z < NOISE_N; z++) {
    gl.framebufferTextureLayer(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, noiseTex, 0, z);
    gl.uniform1f(prog.noise.u.uZ, z + 0.5);
    drawFull();
  }
  gl.bindFramebuffer(gl.FRAMEBUFFER, null);
  gl.deleteFramebuffer(fb);

  simTex = makeTex(SIM_NX, SIM_NY, gl.RGBA8, gl.RGBA, gl.UNSIGNED_BYTE, gl.LINEAR, gl.CLAMP_TO_EDGE, null);
  simDirty = true;
  targets = {};
  sizeKey = '';
}

// ---------------------------------------------------------------------------
// Render targets, quality and camera
// ---------------------------------------------------------------------------
const LEVELS = [
  { scale: 0.5, samples: 0, steam: 0.34, steps: 18 },
  { scale: 0.66, samples: 2, steam: 0.38, steps: 22 },
  { scale: 0.82, samples: 4, steam: 0.42, steps: 28 },
  { scale: 1.0, samples: 4, steam: 0.5, steps: 34 },
];
let quality = 2, qualityCeil = LEVELS.length - 1;
let targets = {}, sizeKey = '', W = 1, Hh = 1;

function resize() {
  const cssW = Math.max(1, canvas.clientWidth || window.innerWidth);
  const cssH = Math.max(1, canvas.clientHeight || window.innerHeight);
  const L = LEVELS[quality];
  const dpr = Math.min(window.devicePixelRatio || 1, 2) * L.scale;
  let w = Math.max(2, Math.round(cssW * dpr)), h = Math.max(2, Math.round(cssH * dpr));
  const cap = 3.6e6;
