const cam = { yaw: 0, pitch: 0, pos: [0, 3, 6], fwd: [0, 0, -1], right: [1, 0, 0], up: [0, 1, 0], tanX: 1, tanY: 1, viewProj: null };
const BASE_EL = 0.67;

function updateCamera() {
  const aspect = W / Hh;
  const fovY = (aspect < 1 ? 36 : 30) * Math.PI / 180;
  const tanY = Math.tan(fovY / 2), tanX = tanY * aspect;
