  [0.1, 0.84, 0.05, 0.05, [1.0, 0.55, 0.22]],
  [0.26, 0.94, 0.034, 0.04, [1.0, 0.7, 0.35]],
  [0.81, 0.88, 0.06, 0.045, [1.0, 0.5, 0.2]],
  [0.93, 0.7, 0.04, 0.03, [0.95, 0.62, 0.3]],
  [0.63, 0.97, 0.028, 0.035, [1.0, 0.75, 0.45]],
